-- Ajout de 20 nouvelles opportunités d'investissement en Afrique

INSERT INTO investment_opportunities (title, slug, sector, subsector, country, country_name, region, summary, description, opportunity_type, min_investment, max_investment, expected_return_min, expected_return_max, investment_horizon, risk_level, company_name, company_size, stage, market_size_usd, source_name, source_url, status) VALUES

-- FINTECH & SERVICES FINANCIERS
('Néobanque Mobile - Afrique de l''Est', 'neobank-mobile-east-africa-2024', 'Finance', 'Fintech', 'KE', 'Kenya', 'Afrique de l''Est', 'Néobanque 100% mobile ciblant les jeunes urbains non-bancarisés, 300K utilisateurs en 12 mois, expansion Tanzanie et Ouganda prévue.', 'Startup kenyane proposant comptes bancaires mobiles sans frais, cartes virtuelles, épargne automatique et micro-crédits instantanés. Modèle freemium avec revenus interchange (0,5% transactions) et premium (2$/mois). Licence bancaire obtenue auprès de la Central Bank of Kenya. Partenariats avec M-Pesa et Airtel Money. Taux d''acquisition client: 15 000/mois. Coût acquisition: 3$. LTV: 45$. Plan: lever 5M USD série A pour expansion régionale et lancement produits d''investissement (actions, obligations, crypto).', 'company', 800000, 5000000, 28, 55, 'medium', 'high', 'Jaza Digital Bank', 'startup', 'early', 8500000000, 'VC4Africa', 'https://example.com/jaza', 'active'),

('Plateforme Assurance Paramétrique - Agriculture', 'parametric-insurance-agriculture-2024', 'Finance', 'InsurTech', 'GH', 'Ghana', 'Afrique de l''Ouest', 'Micro-assurance agricole basée sur données satellites et météo, protégeant 80K petits agriculteurs contre sécheresses et inondations.', 'InsurTech ghanéenne utilisant imagerie satellite, IoT et IA pour assurer automatiquement les récoltes. Paiements instantanés via mobile money dès détection sinistre (sans évaluation terrain). Primes: 5-15$/hectare/saison. Taux de sinistralité: 45%. Partenariats: Ghana Meteorological Agency, CGIAR. Couverture actuelle: riz, maïs, cacao. 80 000 agriculteurs assurés (2023). Expansion prévue: Burkina Faso, Nigeria, avec ajout bétail et pêche. Opportunité: série A pour scaling tech et expansion géographique.', 'company', 1200000, 6000000, 22, 40, 'medium', 'medium', 'AgriShield Africa', 'startup', 'growth', 4200000000, 'IFC Ventures', 'https://example.com/agrishield', 'active'),

-- ÉNERGIE RENOUVELABLE
('Mini-réseaux solaires ruraux - RDC', 'solar-minigrids-drc-2024', 'Énergie', 'Solaire', 'CD', 'RDC', 'Afrique Centrale', 'Déploiement de 50 mini-réseaux solaires électrifiant 200 villages isolés (100K habitants), tarif 0,25$/kWh, subventions gouvernementales.', 'Projet d''électrification rurale en RDC via mini-grids solaires hybrides (PV + batteries + backup diesel). Chaque mini-réseau: 50-200kW, desservant 500-2000 personnes. Modèle pay-as-you-go via mobile money. Contrats PPA 15 ans avec autorités locales. Subvention USAID: 40% CAPEX. TRI projet: 16%. Sites identifiés dans provinces Kasaï, Katanga, Équateur. Partenariat EDF et Engie pour O&M. Phase 1: 10 sites pilotes (financement sécurisé). Phase 2-3: 40 sites additionnels (recherche 12M USD). Impact: 100K bénéficiaires, création 300 emplois locaux.', 'project', 3000000, 15000000, 14, 20, 'long', 'medium', 'Lumière Pour Tous RDC', 'sme', 'early', 2800000000, 'USAID Power Africa', 'https://example.com/lumiere-rdc', 'active'),

('Biogaz agricole et déchets - Rwanda', 'biogas-agriculture-rwanda-2024', 'Énergie', 'Biogaz', 'RW', 'Rwanda', 'Afrique de l''Est', 'Usines de biogaz transformant déchets agricoles en électricité et fertilisant, 15MW capacité totale, contrats fourniture électricité sécurisés.', 'Développement de 3 usines de méthanisation traitant déchets agricoles (café, thé, bananes) et déjections animales. Capacité totale: 15MW électricité + 50K tonnes compost/an. PPAs signés avec Rwanda Energy Group (12 ans, 0,09$/kWh). Matière première: contrats approvisionnement avec 20 coopératives agricoles. Technologie éprouvée (européenne). Incentives: exonération fiscale 7 ans, prime feed-in tariff. Construction: 18 mois. Revenus mixtes: 60% électricité, 25% compost, 15% crédits carbone. Projet aligné stratégie Rwanda Green Growth.', 'project', 8000000, 25000000, 15, 22, 'long', 'low', NULL, NULL, 'early', 1200000000, 'AfDB Green Climate Fund', 'https://example.com/biogas-rwanda', 'active'),

-- AGRITECH & AGRICULTURE
('Blockchain traçabilité café - Éthiopie', 'blockchain-coffee-traceability-ethiopia-2024', 'Tech', 'AgriTech', 'ET', 'Éthiopie', 'Afrique de l''Est', 'Plateforme blockchain garantissant traçabilité et commerce équitable du café éthiopien, 500 coopératives connectées, accès marchés premium internationaux.', 'Startup éthiopienne digitalisant chaîne de valeur du café via blockchain. Chaque lot tracé de la ferme au consommateur (QR codes). Paiement direct producteurs via crypto/mobile money, éliminant intermédiaires (+ 40% revenus fermiers). Accès marchés premium (Specialty Coffee, Fair Trade). 500 coopératives (50K agriculteurs) déjà onboardées. Partenaires: Starbucks, Nespresso en négociation. Revenus: commission 3% transactions + SaaS coopératives. Volume 2023: 15K tonnes, 25M$ GMV. Levée série B pour expansion Afrique de l''Est (Kenya, Tanzanie) et ajout cacao, vanille.', 'company', 2000000, 10000000, 30, 60, 'medium', 'high', 'ChainCoffee Ethiopia', 'startup', 'growth', 32000000000, 'Plug and Play Ventures', 'https://example.com/chaincoffee', 'active'),

('Aquaculture Tilapia - Ouganda', 'tilapia-aquaculture-uganda-2024', 'Agriculture', 'Aquaculture', 'UG', 'Ouganda', 'Afrique de l''Est', 'Ferme aquacole moderne produisant 3000 tonnes tilapia/an, certification ASC, export Europe et Moyen-Orient, techniques d''élevage durables.', 'Développement ferme aquacole 50 hectares sur Lac Victoria, production 3000 tonnes/an tilapia. Système RAS (Recirculating Aquaculture) réduisant consommation eau 90%. Aliments locaux (mouche soldat noir). Certification ASC et Bio EU. Prix vente: 4,5$/kg (export Europe 70%, local 30%). Coût production: 2,2$/kg. Contrats préliminaires avec Carrefour, Metro. Emplois: 120 directs + 300 indirects (logistics, processing). Phase 1 opérationnelle (800 tonnes/an). Recherche 8M$ pour phases 2-3 et usine transformation (filets, fumage).', 'project', 2500000, 10000000, 18, 28, 'medium', 'medium', 'Victoria Tilapia Farms', 'sme', 'growth', 5600000000, 'FMO Netherlands', 'https://example.com/victoria-tilapia', 'active'),

-- SANTÉ & MEDTECH
('Réseau pharmacies franchisées - Tanzanie', 'pharmacy-franchise-tanzania-2024', 'Santé', 'Pharma Retail', 'TZ', 'Tanzanie', 'Afrique de l''Est', 'Réseau de 100 pharmacies franchisées dans villes secondaires tanzaniennes, approvisionnement centralisé, télépharmacie intégrée.', 'Chaîne de pharmacies franchise ciblant villes 50-200K habitants mal desservies. Modèle: centrale d''achat (prix négociés -30%), formation pharmaciens, branding unifié, système de gestion. Services: vente médicaments, téléconsultation médicale, tests rapides (malaria, VIH, diabète). 25 pharmacies ouvertes (2022-2023), objectif 100 d''ici 2026. Rentabilité unitaire: 15K$/an. Coût ouverture: 25K$/pharmacie. Revenus franchiseur: royalties 5% + marge centrale achat 8%. Partenariat Novartis Access pour génériques. Financement recherché: scaling + entrepôt central Dar es Salaam.', 'company', 1500000, 7000000, 24, 38, 'medium', 'medium', 'DawaMart Tanzania', 'sme', 'growth', 3200000000, 'East Africa Ventures', 'https://example.com/dawamart', 'active'),

('Dispositifs médicaux imprimés 3D - Afrique du Sud', '3d-printed-medical-devices-southafrica-2024', 'Santé', 'MedTech', 'ZA', 'Afrique du Sud', 'Afrique Australe', 'Fabrication locale de prothèses et implants orthopédiques via impression 3D, réduction coûts 70%, certifications CE et FDA en cours.', 'Startup sud-africaine produisant prothèses membres, implants dentaires et orthopédiques par impression 3D métal/résine biocompatible. Coût prothèse: 500$ vs 3000$ importée. Délai: 48h vs 8 semaines. Scan 3D patient → design sur-mesure → impression → livraison. Marchés: hôpitaux publics (appels d''offres), cliniques privées, ONG (mines anti-personnel). 1200 prothèses livrées (2023). Certifications: SABS South Africa, CE Europe (obtenue), FDA USA (Q3 2024). Expansion: Nigeria, Kenya, Égypte. Financement: équipements (6 imprimantes industrielles), R&D nouveaux matériaux.', 'company', 1800000, 8000000, 26, 45, 'medium', 'medium', 'AfriPrint Medical', 'startup', 'growth', 8900000000, 'Savannah Fund', 'https://example.com/afriprint-medical', 'active'),

-- IMMOBILIER & CONSTRUCTION
('Logements sociaux préfabriqués - Angola', 'prefab-social-housing-angola-2024', 'Immobilier', 'Construction', 'AO', 'Angola', 'Afrique Australe', 'Construction 2000 logements sociaux modulaires préfabriqués à Luanda, programme gouvernemental, délais construction réduits 60%.', 'Projet de logements sociaux en structures préfabriquées (béton + acier). Unités T2/T3 de 50-70m², assemblage 45 jours/immeuble. Prix vente: 35K$ (vs 60K$ construction traditionnelle). Programme gouvernemental "Casa Para Todos" garantissant acquisition 80% unités. Financement acheteurs: prêts BNA (taux subventionné 4%, 20 ans). Site: périphérie Luanda, infrastructure complète (routes, eau, électricité). Phase 1: 500 unités (financement bouclé). Phases 2-3: 1500 unités (recherche 45M$). Usine de préfabrication locale créant 800 emplois. Marge projet: 18%.', 'project', 15000000, 50000000, 15, 22, 'medium', 'medium', 'ModularHome Angola', 'sme', 'early', 12000000000, 'World Bank IFC', 'https://example.com/modularhome-angola', 'active'),

('Co-working espaces Afrique francophone', 'coworking-spaces-francophone-africa-2024', 'Immobilier', 'Co-working', 'SN', 'Sénégal', 'Multi-pays', 'Réseau de 15 espaces de co-working haut de gamme dans 8 capitales africaines francophones, 5000 membres, services premium pour startups et PME.', 'Opérateur d''espaces de co-working premium ciblant entrepreneurs, freelances, PME dans capitales francophones. 8 sites opérationnels: Dakar, Abidjan, Douala, Kinshasa, Lomé, Cotonou, Bamako, Ouagadougou. Services: bureaux flexibles, salles réunion, fibre optique, événements networking, domiciliation. Abonnements: 50-300$/mois selon formule. Taux occupation: 87%. Revenus 2023: 4,2M$. Plan expansion: 7 nouveaux sites (Libreville, Niamey, Conakry, Antananarivo, Yaoundé, Brazzaville, Bangui). Modèle: location baux commerciaux + rénovation. Objectif: 5000 membres, 15 sites d''ici 2026. Synergies: fonds d''investissement startups membres.', 'company', 3000000, 12000000, 20, 35, 'medium', 'medium', 'Réseau Afrique Co-Work', 'sme', 'growth', 2100000000, 'AfricInvest', 'https://example.com/afrique-cowork', 'active'),

-- TECH & DIGITAL
('Cybersécurité entreprises - Nigeria', 'cybersecurity-enterprises-nigeria-2024', 'Tech', 'Cybersécurité', 'NG', 'Nigeria', 'Afrique de l''Ouest', 'SOC (Security Operations Center) proposant services cybersécurité managés pour PME et grandes entreprises nigérianes, protection contre ransomwares et fraudes.', 'Société de cybersécurité nigériane opérant SOC 24/7 à Lagos. Services: monitoring réseau, détection intrusions, réponse incidents, pentesting, formation employés. Clients: 120 entreprises (banques, télécoms, e-commerce, gouvernement). Abonnements: 1K-10K$/mois selon taille entreprise. Revenus récurrents (ARR): 4,8M$ (+180% YoY). Équipe: 35 experts certifiés (CISSP, CEH). Stack technologique: SIEM, EDR, threat intelligence. Expansion: Ghana, Kenya. Opportunité: croissance cyberattaques Nigeria (+240% 2023), réglementation NCC imposant standards sécurité. Série A pour R&D IA détection menaces et expansion régionale.', 'company', 2500000, 10000000, 28, 50, 'medium', 'high', 'CyberShield Nigeria', 'startup', 'growth', 15000000000, 'TLcom Capital', 'https://example.com/cybershield-ng', 'active'),

('Plateforme e-learning écoles - Afrique francophone', 'elearning-schools-francophone-2024', 'Tech', 'EdTech', 'CI', 'Côte d''Ivoire', 'Multi-pays', 'LMS (Learning Management System) pour écoles primaires/secondaires, 500 établissements clients, contenus curriculum officiel, tableaux blancs interactifs.', 'Plateforme SaaS ivoirienne fournissant contenu pédagogique digital aligné curriculums nationaux. Modules interactifs maths, sciences, français, histoire-géo. 500 écoles abonnées (CI, SN, BF, BJ, TG, ML). 150K élèves utilisateurs. Abonnement: 15$/élève/an (écoles privées), 8$/élève (publiques subventionnées). Services: plateforme web/mobile, formation enseignants, tableaux blancs interactifs. Partenariats ministères Éducation. Revenus 2023: 2,1M$. Plan: expansion 5 nouveaux pays, ajout IA tutorat personnalisé, contenus vocaux langues locales. Marché: 50M élèves Afrique francophone, taux digitalisation écoles <10%.', 'company', 1500000, 6000000, 25, 45, 'medium', 'medium', 'ÉcoDigital Afrique', 'startup', 'growth', 18000000000, 'Partech Africa', 'https://example.com/ecodigital', 'active'),

-- TRANSPORT & LOGISTIQUE
('Flotte Bus Électriques - Maroc', 'electric-buses-morocco-2024', 'Transport', 'Mobilité Électrique', 'MA', 'Maroc', 'Afrique du Nord', 'Déploiement de 200 bus électriques pour transport urbain Casablanca et Rabat, contrats exploitation 12 ans, stations de recharge solaire.', 'Projet de renouvellement flotte transport public par bus électriques. 200 bus 12 mètres (80 passagers), autonomie 300km, recharge 4h. Contrats d''exploitation 12 ans avec Casablanca Transport et Rabat Mobilité. Revenus: billetterie passagers + subventions exploitation. Stations recharge: panneaux solaires (autoconsommation 60%). Investissement: bus (70%), infrastructure (20%), O&M (10%). Constructeur: partenariat BYD ou Yutong. Économies: -70% coûts carburant, -60% maintenance vs diesel. Impact environnemental: -15K tonnes CO2/an. Financement: dette 60%, equity 40%. TRI projet: 11% (incluant valorisation crédits carbone).', 'project', 40000000, 80000000, 10, 16, 'long', 'low', NULL, NULL, 'early', 9000000000, 'AfDB Sustainable Transport', 'https://example.com/e-buses-morocco', 'active'),

('Plateforme logistique e-commerce - Afrique de l''Ouest', 'logistics-ecommerce-westafrica-2024', 'Transport', 'Logistique', 'NG', 'Nigeria', 'Multi-pays', 'Infrastructure logistique pour e-commerce: entrepôts, livraison last-mile, paiement à la livraison, couvrant Nigeria, Ghana, Côte d''Ivoire.', 'Opérateur logistique 3PL spécialisé e-commerce en Afrique de l''Ouest. Services: warehousing, fulfillment, livraison urbaine/régionale, cash-on-delivery, reverse logistics. Infrastructure: 8 entrepôts (Lagos, Abuja, Port Harcourt, Accra, Kumasi, Abidjan, Cotonou), 500 livreurs, flotte 100 véhicules. Clients: Jumia, Konga, merchants locaux. Volume: 50K colis/mois. Délai livraison: 24-72h urbain. Technologie: TMS propriétaire, tracking temps réel, API intégration. Revenus: frais traitement colis (2-5$/unité). Croissance e-commerce Afrique Ouest: 25% CAGR. Financement: expansion Sénégal, Bénin, Togo + automatisation entrepôts.', 'company', 5000000, 20000000, 22, 38, 'medium', 'medium', 'AfriLogistics Hub', 'sme', 'growth', 28000000000, 'Novastar Ventures', 'https://example.com/afrilogistics', 'active'),

-- INDUSTRIE & MANUFACTURING
('Usine textile coton bio - Bénin', 'organic-cotton-textile-benin-2024', 'Industrie', 'Textile', 'BJ', 'Bénin', 'Afrique de l''Ouest', 'Filature et tissage de coton biologique béninois, production 5000 tonnes tissu/an, certifications GOTS et Fair Trade, export Europe.', 'Usine intégrée de transformation coton: égrainage, filage, tissage, teinture naturelle. Capacité: 5000 tonnes tissu/an. Approvisionnement: 50 coopératives coton bio (15K producteurs) via contrats pluriannuels. Certifications: GOTS (Global Organic Textile Standard), Fair Trade, Oeko-Tex. Marchés: export 70% (marques européennes mode éthique: Patagonia, Veja, etc.), local 30%. Prix vente: 12$/kg tissu (vs 8$/kg conventionnel). Emplois: 400 directs. Économie circulaire: déchets valorisés (compost, biogaz). Financement recherché: équipements tissage haute technologie + unité teinture aux plantes. Programme appuyé par GIZ et Fairtrade International.', 'project', 10000000, 30000000, 16, 24, 'long', 'medium', 'Bénin Organic Textiles', 'sme', 'early', 4500000000, 'IFC Sustainability', 'https://example.com/benin-textile', 'active'),

('Recyclage plastique - Kenya', 'plastic-recycling-kenya-2024', 'Industrie', 'Recyclage', 'KE', 'Kenya', 'Afrique de l''Est', 'Usine de recyclage collectant 15K tonnes déchets plastique/an, production granulés et produits manufacturés, contrats collecte municipalités.', 'Société kenyane de collecte et recyclage de plastiques (PET, HDPE, PP). Collecte: réseau 500 centres communautaires (rémunération collecteurs), contrats municipalités Nairobi, Mombasa, Kisumu. Volume traité: 15K tonnes/an. Procédés: tri, lavage, broyage, extrusion granulés. Production: granulés recyclés (50%, vente industries), produits finis (50%): pavés, mobilier urbain, conteneurs. Partenariats: Coca-Cola (bouteilles rPET), Unilever. Revenus: 8M$ (2023). Emplois: 300 directs + 2000 collecteurs informels. Expansion: 2ème usine Ouganda, ajout recyclage textile. Financement: équipements, R&D nouveaux produits. Impact: détournement 15K tonnes plastique de décharges/océan.', 'company', 4000000, 15000000, 20, 32, 'medium', 'medium', 'GreenCycle East Africa', 'sme', 'growth', 6200000000, 'Circulate Capital', 'https://example.com/greencycle', 'active'),

-- TOURISME & HÔTELLERIE
('Écolodges Safari - Botswana', 'eco-safari-lodges-botswana-2024', 'Tourisme', 'Écotourisme', 'BW', 'Botswana', 'Afrique Australe', 'Réseau de 5 écolodges luxe dans réserves privées, 100% énergie solaire, tourisme premium, conservation biodiversité et emplois communautés locales.', 'Développement de 5 écolodges haut de gamme (20-30 chambres chacun) dans concessions privées delta Okavango et Chobe. Positionnement: tourisme premium (800-1500$/nuit), safaris guidés, observation faune, expériences immersives. 100% énergie renouvelable (solaire + batteries), gestion eau durable, architecture locale. Modèle: revenus redistribués 15% communautés locales, emploi prioritaire populations autochtones (San, Bayei). Partenariats conservation: WWF, Elephants Without Borders. Clientèle: touristes internationaux haut de gamme (Europe, USA, Asie). Saison haute: mai-octobre (occupation 90%). Construction écologique premium. Financement: développement lodges + fonds conservation.', 'project', 12000000, 35000000, 18, 28, 'long', 'medium', 'Okavango Eco Retreats', 'sme', 'early', 3800000000, 'Conservation International', 'https://example.com/okavango-lodges', 'active'),

-- MINES & RESSOURCES NATURELLES
('Mine Lithium - Zimbabwe', 'lithium-mining-zimbabwe-2024', 'Mines', 'Lithium', 'ZW', 'Zimbabwe', 'Afrique Australe', 'Exploitation mine lithium (spodumène) réserves prouvées 12 millions tonnes LCE, production 200K tonnes/an, demande batteries véhicules électriques.', 'Projet minier lithium dans région Masvingo, Zimbabwe. Ressources géologiques: 12M tonnes Lithium Carbonate Equivalent (LCE). Méthode: extraction à ciel ouvert, concentration sur site, export spodumène (6% Li2O) vers raffineries Chine/Europe. Production estimée: 200K tonnes spodumène/an pendant 25 ans. Prix vente: 1200$/tonne (spot). Coût extraction: 400$/tonne. Permis exploitation obtenu. Convention minière: royalties 5%, impôt sociétés 25%. Infrastructure: route minière, ligne électrique, camp minier. Partenariat potentiel constructeurs automobiles (offtake agreements). Transition énergétique: demande lithium batteries × 5 d''ici 2030. Financement: CAPEX mine + usine concentration.', 'project', 80000000, 200000000, 20, 35, 'long', 'high', NULL, NULL, 'early', 65000000000, 'Mining Indaba', 'https://example.com/lithium-zimbabwe', 'active'),

-- ÉCONOMIE BLEUE
('Transformation poisson - Mauritanie', 'fish-processing-mauritania-2024', 'Agriculture', 'Pêche', 'MR', 'Mauritanie', 'Afrique de l''Ouest', 'Usine moderne de transformation poisson (filetage, congélation, conserves), capacité 15K tonnes/an, certifications export UE et USA.', 'Usine de transformation produits halieutiques mauritaniens: poulpe, crevettes, poissons blancs. Procédés: réception, tri, filetage automatisé, surgélation IQF, conditionnement. Capacité: 15K tonnes produits finis/an. Approvisionnement: contrats armateurs pêche locale + achats criée Nouakchott. Certifications: HACCP, MSC (pêche durable), agréments sanitaires UE/USA. Marchés: export 85% (Espagne, France, Japon, USA), local 15%. Emplois: 350 permanents + 200 saisonniers (dont 70% femmes). Opportunité: stocks halieutiques mauritaniens (meilleurs Afrique), quotas pêche UE, demande croissante produits premium. Financement: modernisation lignes production, extension capacité stockage froid, certification bio.', 'project', 6000000, 18000000, 17, 26, 'medium', 'medium', 'Océan Mauritanie Industries', 'sme', 'growth', 2900000000, 'BOAD', 'https://example.com/ocean-mauritanie', 'active');

